// HIPAA-style guardrail: strip personal data BEFORE anything is sent to the LLM.
const patterns = [
  [/[\w.+-]+@[\w-]+\.[\w.]+/g, '[EMAIL]'],
  [/\b(MBR|MEM)[-\s]?\d{6,}\b/gi, '[MEMBER_ID]'],
  [/\+?\d[\d\s-]{8,}\d/g, '[PHONE]'],
];
return $input.all().map(item => {
  const inc = { ...item.json };
  let count = 0;
  for (const field of ['short_description', 'description']) {
    let text = String(inc[field] ?? '');
    for (const [re, tag] of patterns) text = text.replace(re, () => { count++; return tag; });
    inc[field] = text;
  }
  inc.pii_redactions = count;
  return { json: inc };
});

// Knowledge retrieval: find the most similar past incidents (lightweight keyword scoring).
// In production, swap this for a vector store / Jira / ServiceNow search.
const KB = [
  { id: 'INC0081234', category: 'Access',   group: 'Citrix & VDI',      title: 'Citrix published desktop fails to launch - Cannot start desktop', resolution: 'Delivery Controller lost registration with the VDA machine catalogue after patching. Re-registered VDAs and restarted the Broker service; users relaunched sessions.' },
  { id: 'INC0079911', category: 'Access',   group: 'Citrix & VDI',      title: 'Multiple users Citrix Workspace cannot start desktop after maintenance', resolution: 'StoreFront base URL certificate expired. Renewed certificate on StoreFront servers and reset Workspace app cache on affected machines.' },
  { id: 'INC0076540', category: 'Access',   group: 'Identity & Access', title: 'User locked out of Active Directory account', resolution: 'Unlocked account in AD, cleared cached credentials on mobile device causing repeated lockouts.' },
  { id: 'INC0072201', category: 'Email',    group: 'Messaging (M365)',  title: 'Outlook not syncing new emails', resolution: 'Rebuilt Outlook profile and cleared OST file; mailbox synced.' },
  { id: 'INC0070088', category: 'Network',  group: 'Network Ops',       title: 'VPN disconnects every 10 minutes for remote users', resolution: 'Increased idle timeout on VPN concentrator and pushed updated client profile.' },
  { id: 'INC0068815', category: 'Software', group: 'Desktop Support',   title: 'Claims application crashes on launch after update', resolution: 'Rolled back faulty client update via SCCM and raised vendor ticket.' },
  { id: 'INC0066420', category: 'Hardware', group: 'Desktop Support',   title: 'Laptop docking station monitors not detected', resolution: 'Updated dock firmware and display drivers.' },
  { id: 'INC0064102', category: 'Security', group: 'Security Ops',      title: 'Suspicious phishing email reported by several users', resolution: 'Purged message tenant-wide, blocked sender domain, reset passwords for users who clicked.' },
];
const STOP = new Set(['the','and','for','are','but','not','with','when','after','about','users','user','team','they','get','from','this','that','please','since','opening','fine']);
const tokens = s => (String(s).toLowerCase().match(/[a-z0-9]+/g) || []).filter(w => w.length > 2 && !STOP.has(w));

const inc = $input.first().json;
const query = new Set(tokens(inc.short_description + ' ' + inc.description));
const ranked = KB.map(k => {
  const doc = new Set(tokens(k.title + ' ' + k.resolution));
  let hits = 0;
  for (const w of query) if (doc.has(w)) hits++;
  const score = hits / Math.sqrt((query.size * doc.size) || 1);
  return { ...k, score: Number(score.toFixed(3)) };
}).filter(k => k.score > 0).sort((a, b) => b.score - a.score).slice(0, 3);

return [{ json: { ...inc, similar_incidents: ranked } }];

