// Guardrail: never trust raw LLM output. Validate it, then decide if a human must approve.
const ctx = $('Retrieve Similar Past Resolutions').first().json;
const CATEGORIES = ['Access', 'Network', 'Email', 'Hardware', 'Software', 'Security'];
const PRIORITIES = ['P1', 'P2', 'P3', 'P4'];
const GROUPS = ['Citrix & VDI', 'Identity & Access', 'Messaging (M365)', 'Network Ops', 'Desktop Support', 'Security Ops'];

const errors = [];
let ai = {};
try {
  ai = JSON.parse($input.first().json.choices[0].message.content);
} catch (e) {
  errors.push('AI output was not valid JSON');
}
if (!CATEGORIES.includes(ai.category)) errors.push(`invalid category: ${ai.category}`);
if (!PRIORITIES.includes(ai.priority)) errors.push(`invalid priority: ${ai.priority}`);
if (!GROUPS.includes(ai.assignment_group)) errors.push(`invalid assignment group: ${ai.assignment_group}`);

const retrieved = new Set((ctx.similar_incidents || []).map(s => s.id));
const claimed = Array.isArray(ai.cited_incidents) ? ai.cited_incidents : [];
const cited = claimed.filter(id => retrieved.has(id));
if (cited.length !== claimed.length) errors.push('AI cited an incident that was not retrieved');

const confidence = Number(ai.confidence);
const reasons = [...errors];
if (['P1', 'P2'].includes(ai.priority)) reasons.push(`high priority (${ai.priority})`);
if (!(confidence >= 0.75)) reasons.push(`confidence below 0.75 (${ai.confidence})`);

return [{ json: {
  incident_id: ctx.incident_id,
  short_description: ctx.short_description,
  pii_redactions: ctx.pii_redactions,
  category: ai.category ?? null,
  priority: ai.priority ?? null,
  assignment_group: ai.assignment_group ?? null,
  summary: ai.summary ?? null,
  suggested_resolution: ai.suggested_resolution ?? null,
  cited_incidents: cited,
  draft_reply: ai.draft_reply ?? null,
  confidence: Number.isFinite(confidence) ? confidence : null,
  validation_errors: errors,
  needs_review: reasons.length > 0,
  review_reasons: reasons,
} }];
